public async Task<List<string>> GetPopularPostTitlesAsync(
    BlogContext context,
    CancellationToken cancellationToken = default)
{
    var popularPostTitles =
        from post in context.Posts
        where post.Views > 100
        orderby post.Views descending
        select post.Title;

    var titles = await popularPostTitles.ToListAsync(cancellationToken);

    return titles;
}
